BEGIN;SET LOCAL statement_timeout='8s';SET LOCAL lock_timeout='1s';SELECT pg_advisory_xact_lock(2026083000261022);
DO $patch$ DECLARE old text;updated text;r record;BEGIN
IF EXISTS(SELECT 1 FROM cron.job WHERE jobid=596 AND active) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton AND owner_id='top3000-recovery-20261023-root-4b1314bcb5c2' AND owner_fence=2 AND stop_generation=0 AND enabled AND NOT stopped AND hold_reason IS NULL AND admitted_until>clock_timestamp()) THEN RAISE EXCEPTION 'PAUSED_CURRENT_ROOT_REQUIRED';END IF;
